#include <stdint.h>

/*
 * Minimal CMSIS-style register definitions.
 * The project is intentionally HAL/CubeMX-free, so these definitions keep
 * main.c self-contained while preserving the RCC-> and GPIOx-> notation.
 */
typedef struct
{
    volatile uint32_t MODER;
    volatile uint32_t OTYPER;
    volatile uint32_t OSPEEDR;
    volatile uint32_t PUPDR;
    volatile uint32_t IDR;
    volatile uint32_t ODR;
    volatile uint32_t BSRR;
} GPIO_TypeDef;

typedef struct
{
    volatile uint32_t CR;
    volatile uint32_t ICSCR;
    volatile uint32_t CFGR;
    volatile uint32_t PLLCFGR;
    volatile uint32_t PLLSAI1CFGR;
    volatile uint32_t CIER;
    volatile uint32_t CIFR;
    volatile uint32_t CICR;
    volatile uint32_t AHB1RSTR;
    volatile uint32_t AHB2RSTR;
    volatile uint32_t AHB3RSTR;
    uint32_t RESERVED0;
    volatile uint32_t APB1RSTR1;
    volatile uint32_t APB1RSTR2;
    volatile uint32_t APB2RSTR;
    uint32_t RESERVED1[3];
    volatile uint32_t AHB1ENR;
    volatile uint32_t AHB2ENR;
} RCC_TypeDef;

#define GPIOA ((GPIO_TypeDef *)0x48000000UL)
#define GPIOC ((GPIO_TypeDef *)0x48000800UL)
#define RCC   ((RCC_TypeDef *)0x40021000UL)

#define GPIOAEN              (1UL << 0)
#define GPIOCEN              (1UL << 2)
#define LED_PIN              5U
#define BUTTON_PIN           13U
#define BUTTON_MASK          (1UL << BUTTON_PIN)
#define DEBOUNCE_CYCLES      250000U
#define SERVICE_CHUNK_CYCLES 10000U

/*
 * startup_stm32l476rgtx.s calls SystemInit before main().
 * No clock reconfiguration is needed here: after reset the MCU runs from
 * HSI16, which is sufficient for this first GPIO test.
 */
void SystemInit(void)
{
}

static void delay(volatile uint32_t cycles)
{
    while (cycles-- != 0U)
    {
        __asm volatile ("nop");
    }
}

static void gpio_init(void)
{
    RCC->AHB2ENR |= GPIOAEN | GPIOCEN;
    (void)RCC->AHB2ENR; /* Allow the peripheral clock write to take effect. */

    /* PA5: general-purpose push-pull output, initially low. */
    GPIOA->MODER &= ~(3UL << (2U * LED_PIN));
    GPIOA->MODER |=  (1UL << (2U * LED_PIN));
    GPIOA->OTYPER &= ~(1UL << LED_PIN);
    GPIOA->PUPDR &= ~(3UL << (2U * LED_PIN));
    GPIOA->BSRR = (1UL << (LED_PIN + 16U));

    /*
     * PC13: input with pull-up. B1 is active-low on NUCLEO-L476RG:
     * released = 1, pressed = 0.
     */
    GPIOC->MODER &= ~(3UL << (2U * BUTTON_PIN));
    GPIOC->PUPDR &= ~(3UL << (2U * BUTTON_PIN));
    GPIOC->PUPDR |=  (1UL << (2U * BUTTON_PIN));
}

static uint32_t button_pressed(void)
{
    return (GPIOC->IDR & BUTTON_MASK) == 0U;
}

static void led_on(void);
static void led_off(void);

static uint32_t button_press_event(void)
{
    if (!button_pressed())
    {
        return 0U;
    }

    /* Confirm that the low level is stable before accepting the press. */
    delay(DEBOUNCE_CYCLES);
    if (!button_pressed())
    {
        return 0U;
    }

    /*
     * Wait for release so one long press produces exactly one event.
     * The LED state is changed by the caller immediately after return.
     */
    while (button_pressed())
    {
    }
    delay(DEBOUNCE_CYCLES);

    return 1U;
}

static void delay_with_button(volatile uint32_t cycles, uint32_t *manual_on)
{
    while (cycles != 0U)
    {
        uint32_t chunk = cycles;

        if (chunk > SERVICE_CHUNK_CYCLES)
        {
            chunk = SERVICE_CHUNK_CYCLES;
        }

        delay(chunk);
        cycles -= chunk;

        if (button_press_event())
        {
            *manual_on ^= 1U;
            if (*manual_on)
            {
                led_on();
            }
            else
            {
                led_off();
            }
        }
    }
}

static void led_on(void)
{
    GPIOA->BSRR = (1UL << LED_PIN);
}

static void led_off(void)
{
    GPIOA->BSRR = (1UL << (LED_PIN + 16U));
}

int main(void)
{
    uint32_t manual_on = 0U;

    gpio_init();

    for (;;)
    {
        if (button_press_event())
        {
            manual_on ^= 1U;
        }

        if (manual_on)
        {
            led_on();
            continue;
        }

        /* A washer-like cycle: two short flashes, then one long pause. */
        led_on();
        delay_with_button(700000U, &manual_on);
        if (manual_on)
        {
            continue;
        }

        led_off();
        delay_with_button(250000U, &manual_on);
        if (manual_on)
        {
            continue;
        }

        led_on();
        delay_with_button(700000U, &manual_on);
        if (manual_on)
        {
            continue;
        }

        led_off();
        delay_with_button(250000U, &manual_on);
        delay_with_button(1800000U, &manual_on);
    }
}
